CREATE TABLE announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title STRING NOT NULL, body STRING NOT NULL, type STRING NOT NULL DEFAULT 'info', created_by_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ, deleted_by_user_id UUID REFERENCES users(id));
CREATE TABLE module_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), program_id UUID NOT NULL REFERENCES programs(id), code STRING NOT NULL, name STRING NOT NULL, semester INT2 NOT NULL CHECK(semester IN (1,2)), status STRING NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ, deleted_by_user_id UUID REFERENCES users(id));
CREATE INDEX module_requests_status_idx ON module_requests(status,created_at DESC);
CREATE INDEX module_requests_user_idx ON module_requests(user_id);
CREATE INDEX module_requests_program_idx ON module_requests(program_id);
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), type STRING NOT NULL, message STRING NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE INDEX notifications_unread_idx ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;
CREATE TABLE paper_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), paper_id UUID NOT NULL REFERENCES papers(id), reviewer_user_id UUID NOT NULL REFERENCES users(id), action STRING NOT NULL, reason STRING NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX reviews_paper_idx ON paper_reviews(paper_id);
CREATE INDEX reviews_reviewer_idx ON paper_reviews(reviewer_user_id);
CREATE TABLE flagged_reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), paper_id UUID NOT NULL REFERENCES papers(id), user_id UUID REFERENCES users(id), reason STRING NOT NULL, status STRING NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX flags_status_idx ON flagged_reports(status,created_at DESC);
CREATE INDEX flags_paper_idx ON flagged_reports(paper_id);
CREATE INDEX flags_user_idx ON flagged_reports(user_id);
CREATE TABLE takedown_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), paper_id UUID NOT NULL REFERENCES papers(id), email STRING NOT NULL, reason STRING NOT NULL, status STRING NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX takedowns_status_idx ON takedown_requests(status,created_at DESC);
CREATE INDEX takedowns_paper_idx ON takedown_requests(paper_id);
CREATE TABLE achievements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code STRING NOT NULL UNIQUE, title STRING NOT NULL);
CREATE TABLE user_achievements (user_id UUID NOT NULL REFERENCES users(id), achievement_id UUID NOT NULL REFERENCES achievements(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,achievement_id));
CREATE INDEX user_achievements_achievement_idx ON user_achievements(achievement_id);
ALTER TABLE xp_ledger ADD CONSTRAINT xp_event_type_check CHECK(event_type IN ('APPROVED_PAPER','MARKING_SCHEME','SUPPLEMENTARY','MILESTONE','ADMIN_ADJUSTMENT'));
ALTER TABLE xp_ledger ADD CONSTRAINT xp_grant_reason_check CHECK(event_type!='ADMIN_ADJUSTMENT' OR length(trim(reason))>0);
CREATE INDEX stored_files_owner_idx ON stored_files(owner_user_id);
CREATE INDEX papers_reviewer_idx ON papers(reviewed_by_user_id);
CREATE INDEX papers_marking_idx ON papers(marking_scheme_file_id);
CREATE INDEX announcements_author_idx ON announcements(created_by_user_id);
CREATE INDEX audit_actor_idx ON audit_logs(actor_user_id);
CREATE INDEX username_registry_user_idx ON username_registry(user_id);
